        DerivativeStructure dsX = new DerivativeStructure(2, maxOrder, 0, x0);
        DerivativeStructure dsY = new DerivativeStructure(2, maxOrder, 1, y0);
        DerivativeStructure atan2 = DerivativeStructure.atan2(dsY, dsX);
