    final double mean = 3;
    final double sigma = 4;
    final Gaussian.Parametric f = new Gaussian.Parametric();
    final double x = 1;
    final double[] grad = f.gradient(1, new double[] { norm, mean, sigma });
    final double diff = x - mean;
