@Test
public void testDerivativeMultivariate() {
    final double a = 1.5;
    final double b = 0.5;
    final double c = 0.25;
    final MultivariateDifferentiableFunction mdf = new MultivariateDifferentiableFunction() {

        @Override
        public double value(double[] point) {
            return a * point[0] * point[0] + b * point[1] * point[1] + c * point[0] * point[1];
        }

        @Override
        public DerivativeStructure value(DerivativeStructure[] point) {
            DerivativeStructure x = point[0];
            DerivativeStructure y = point[1];
            DerivativeStructure x2 = x.multiply(x);
            DerivativeStructure y2 = y.multiply(y);
            DerivativeStructure xy = x.multiply(y);
            return x2.multiply(a).add(y2.multiply(b)).add(xy.multiply(c));
        }
    };
    final MultivariateFunction f = FunctionUtils.derivative(mdf, new int[] { 0, 0 });
    final MultivariateFunction dfdx = FunctionUtils.derivative(mdf, new int[] { 1, 0 });
    final MultivariateFunction dfdy = FunctionUtils.derivative(mdf, new int[] { 0, 1 });
    final MultivariateFunction d2fdx2 = FunctionUtils.derivative(mdf, new int[] { 2, 0 });
    final MultivariateFunction d2fdy2 = FunctionUtils.derivative(mdf, new int[] { 0, 2 });
    final MultivariateFunction d2fdxdy = FunctionUtils.derivative(mdf, new int[] { 1, 1 });
    for (double x = -1.0; x < 1; x += 0.01) {
        for (double y = -1.0; y < 1; y += 0.01) {
            Assert.assertEquals(a * x * x + b * y * y + c * x * y, f.value(new double[] { x, y }), 1.0e-15);
            Assert.assertEquals(2 * a * x + c * y, dfdx.value(new double[] { x, y }), 1.0e-15);
            Assert.assertEquals(2 * b * y + c * x, dfdy.value(new double[] { x, y }), 1.0e-15);
            Assert.assertEquals(2 * a, d2fdx2.value(new double[] { x, y }), 1.0e-15);
            Assert.assertEquals(2 * b, d2fdy2.value(new double[] { x, y }), 1.0e-15);
            Assert.assertEquals(c, d2fdxdy.value(new double[] { x, y }), 1.0e-15);
        }
    }
}

/**
 * Tests that a given rule rule will be computed and added once to the cache
 * whatever the number of times this rule is called concurrently.
 */
@Test
public void testConcurrentCreation() throws InterruptedException, ExecutionException {
    // Number of times the same rule will be called.
    final int numTasks = 20;
    final ThreadPoolExecutor exec = new ThreadPoolExecutor(3, numTasks, 1, TimeUnit.SECONDS, new ArrayBlockingQueue<Runnable>(2));
    final List<Future<Pair<double[], double[]>>> results = new ArrayList<Future<Pair<double[], double[]>>>();
    for (int i = 0; i < numTasks; i++) {
        results.add(exec.submit(new RuleBuilder()));
    }
    // Ensure that all computations have completed.
    for (Future<Pair<double[], double[]>> f : results) {
        f.get();
    }
    // Assertion would fail if "getRuleInternal" were not "synchronized".
    final int n = RuleBuilder.getNumberOfCalls();
    Assert.assertEquals("Rule computation was called " + n + " times", 1, n);
}

/**
 * Checks that the value of the integral of each monomial
 *   <code>x<sup>0</sup>, ... , x<sup>p</sup></code>
 * returned by the quadrature rule under test conforms with the expected
 * value.
 * Here {@code p} denotes the degree of the highest polynomial for which
 * exactness is to be expected.
 */
@Test
public void testAllMonomials() {
    for (int n = 0; n <= maxDegree; n++) {
        final double expected = getExpectedValue(n);
        final Power monomial = new Power(n);
        final double actual = integrator.integrate(monomial);
        // System.out.println(n + "/" + maxDegree + " " + integrator.getNumberOfPoints()
        //                    + " " + expected + " " + actual + " " + Math.ulp(expected));
        if (expected == 0) {
            Assert.assertEquals("while integrating monomial x**" + n + " with a " + integrator.getNumberOfPoints() + "-point quadrature rule", expected, actual, eps);
        } else {
            double err = FastMath.abs(actual - expected) / Math.ulp(expected);
            Assert.assertEquals("while integrating monomial x**" + n + " with a " + +integrator.getNumberOfPoints() + "-point quadrature rule, " + " error was " + err + " ulps", expected, actual, Math.ulp(expected) * numUlps);
        }
    }
}

