@Test
public void testGoodnessOfFit() {
    final UniformRandomProvider rng = RandomSource.create(RandomSource.WELL_19937_A, 123456789L);
    final int numSamples = 1000;
    final double level = 0.01;
    for (final double alpha : alphaBetas) {
        for (final double beta : alphaBetas) {
            final BetaDistribution betaDistribution = new BetaDistribution(alpha, beta);
            final RealDistribution.Sampler sampler = betaDistribution.createSampler(rng);
            final double[] observed = AbstractRealDistribution.sample(numSamples, sampler);
            Assert.assertFalse("G goodness-of-fit test rejected null at alpha = " + level, gTest(betaDistribution, observed) < level);
            Assert.assertFalse("KS goodness-of-fit test rejected null at alpha = " + level, new KolmogorovSmirnovTest(RandomSource.JDK, 3448845623L).kolmogorovSmirnovTest(betaDistribution, observed) < level);
        }
    }
}

