            return null;
        }
    };
    final long start = System.nanoTime();
    final long duration = 3;
    final FixedElapsedTime tec = new FixedElapsedTime(duration, TimeUnit.SECONDS);
    while (!tec.isSatisfied(pop)) {
        try {
