    FieldVector3D<DerivativeStructure> v2 = createVector(-4, 2, 0, 3);
    Assert.assertEquals(0.0, FieldVector3D.distance1(createVector(-1, 0, 0, 3), createVector(-1, 0, 0, 3)).getReal(), 0);
