@Test
public void testAccurateCrossProduct() {
    // the vectors u1 and u2 are nearly but not exactly anti-parallel
    // (7.31e-16 degrees from 180 degrees) naive cross product (i.e.
    // computing u1.x * u2.x + u1.y * u2.y + u1.z * u2.z
    // leads to a result of   [0.0009765, -0.0001220, -0.0039062],
    // instead of the correct [0.0006913, -0.0001254, -0.0007909]
    final FieldVector3D<DerivativeStructure> u1 = createVector(-1321008684645961.0 / 268435456.0, -5774608829631843.0 / 268435456.0, -7645843051051357.0 / 8589934592.0, 3);
    final FieldVector3D<DerivativeStructure> u2 = createVector(1796571811118507.0 / 2147483648.0, 7853468008299307.0 / 2147483648.0, 2599586637357461.0 / 17179869184.0, 3);
    final FieldVector3D<DerivativeStructure> u3 = createVector(12753243807587107.0 / 18446744073709551616.0, -2313766922703915.0 / 18446744073709551616.0, -227970081415313.0 / 288230376151711744.0, 3);
    FieldVector3D<DerivativeStructure> cNaive = new FieldVector3D<DerivativeStructure>(u1.getY().multiply(u2.getZ()).subtract(u1.getZ().multiply(u2.getY())), u1.getZ().multiply(u2.getX()).subtract(u1.getX().multiply(u2.getZ())), u1.getX().multiply(u2.getY()).subtract(u1.getY().multiply(u2.getX())));
    FieldVector3D<DerivativeStructure> cAccurate = FieldVector3D.crossProduct(u1, u2);
    Assert.assertTrue(FieldVector3D.distance(u3, cNaive).getReal() > 2.9 * u3.getNorm().getReal());
    Assert.assertEquals(0.0, FieldVector3D.distance(u3, cAccurate).getReal(), 1.0e-30 * cAccurate.getNorm().getReal());
}

@Test
public void testCrossProduct() {
    // we compare accurate versus naive cross product implementations
    // on regular vectors (i.e. not extreme cases like in the previous test)
    UniformRandomProvider random = RandomSource.create(RandomSource.WELL_1024_A, 885362227452043214l);
    for (int i = 0; i < 10000; ++i) {
        double ux = random.nextDouble();
        double uy = random.nextDouble();
        double uz = random.nextDouble();
        double vx = random.nextDouble();
        double vy = random.nextDouble();
        double vz = random.nextDouble();
        Vector3D cNaive = new Vector3D(uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx);
        FieldVector3D<DerivativeStructure> uds = createVector(ux, uy, uz, 3);
        FieldVector3D<DerivativeStructure> vds = createVector(vx, vy, vz, 3);
        Vector3D v = new Vector3D(vx, vy, vz);
        checkVector(FieldVector3D.crossProduct(uds, vds), cNaive.getX(), cNaive.getY(), cNaive.getZ(), 0, vz - uz, uy - vy, uz - vz, 0, vx - ux, vy - uy, ux - vx, 0);
        checkVector(FieldVector3D.crossProduct(uds, v), cNaive.getX(), cNaive.getY(), cNaive.getZ(), 0, vz, -vy, -vz, 0, vx, vy, -vx, 0);
    }
}

