    Assert.assertTrue(!p.contains(p3));
    p = p.rotate(p1, new Rotation(oldNormal, 0.1, RotationConvention.VECTOR_OPERATOR));
    Assert.assertTrue(!p.contains(p1));
    Assert.assertTrue(!p.contains(p2));
    Assert.assertTrue(!p.contains(p3));
}

