    ArcsSet set = (ArcsSet) factory.intersection(factory.union(factory.difference(new ArcsSet(1.0, 6.0, 1.0e-10), new ArcsSet(3.0, 5.0, 1.0e-10)), new ArcsSet(0.5, 2.0, 1.0e-10)), new ArcsSet(0.0, 5.5, 1.0e-10));
