    Assert.assertEquals(expected, m);
    m.setSubMatrix(detData2, 0, 0);
    expected = createSparseMatrix(new double[][] { { 1.0, 3.0, 3.0 }, { 2.0, 4.0, 3.0 }, { 1.0, 2.0, 4.0 } });
    Assert.assertEquals(expected, m);
    m.setSubMatrix(testDataPlus2, 0, 0);
