/**
 * Test equality of covariance. chk: covariance of two
 * samples separately and adds them together. cov: computes
 * covariance of the combined sample showing both are equal.
 */
@Test
public void testEquivalence() {
    int num_sets = 2;
    // covariance of the superset
    StorelessBivariateCovariance cov = new StorelessBivariateCovariance();
    // check covariance made by appending covariance of subsets
    StorelessBivariateCovariance chk = new StorelessBivariateCovariance();
    // Seed can be changed
    final UniformRandomProvider rand = RandomSource.create(RandomSource.ISAAC, 10L);
    for (int s = 0; s < num_sets; s++) {
        // loop through sets of samlpes
        StorelessBivariateCovariance covs = new StorelessBivariateCovariance();
        for (int i = 0; i < 5; i++) {
            // loop through individual samlpes.
            double x = rand.nextDouble();
            double y = rand.nextDouble();
            // add sample to the subset
            covs.increment(x, y);
            // add sample to the superset
            cov.increment(x, y);
        }
        chk.append(covs);
    }
