/**
 * Make sure that permuted arrays do not hash to the same value.
 */
@Test
public void testPermutedArrayHash() {
    double[] original = new double[10];
    double[] permuted = new double[10];
    final UniformRandomProvider random = RandomSource.create(RandomSource.WELL_512_A, 64925784252L);
    // Generate 10 distinct random values
    for (int i = 0; i < 10; i++) {
        final RealDistribution.Sampler u = new UniformRealDistribution(i + 0.5, i + 0.75).createSampler(random);
        original[i] = u.sample();
    }
    // Generate a random permutation, making sure it is not the identity
    boolean isIdentity = true;
    do {
        int[] permutation = MathArrays.natural(10);
        MathArrays.shuffle(permutation, random);
        for (int i = 0; i < 10; i++) {
            if (i != permutation[i]) {
                isIdentity = false;
                break;
            }
            permuted[i] = original[permutation[i]];
        }
    } while (isIdentity);
    // Verify that permuted array has different hash
    Assert.assertFalse(MathUtils.hash(original) == MathUtils.hash(permuted));
}

